import{_ as a,o as i,c as n,ag as e}from"./chunks/framework.CZxGLIO_.js";const c=JSON.parse('{"title":"生产部署","description":"以 Linux systemd 与 Caddy 为例运行 GooseForum，并检查 HTTPS、权限和代理配置。","frontmatter":{"title":"生产部署","description":"以 Linux systemd 与 Caddy 为例运行 GooseForum，并检查 HTTPS、权限和代理配置。"},"headers":[],"relativePath":"docs/gooseforum/deployment/index.md","filePath":"docs/gooseforum/deployment/index.md"}'),t={name:"docs/gooseforum/deployment/index.md"};function l(p,s,h,o,r,k){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="生产部署" tabindex="-1">生产部署 <a class="header-anchor" href="#生产部署" aria-label="Permalink to &quot;生产部署&quot;">​</a></h1><p>以下是 <strong>Linux + systemd + 同机 Caddy</strong> 的部署示例，需要已有域名、服务器及已安装的 Caddy。路径、账号和域名均需按实际环境调整；这些服务文件是本文建议，并非 GooseForum 自带安装器。</p><h2 id="固定目录与运行身份" tabindex="-1">固定目录与运行身份 <a class="header-anchor" href="#固定目录与运行身份" aria-label="Permalink to &quot;固定目录与运行身份&quot;">​</a></h2><p>建议将程序、<code>config.toml</code>、<code>storage/</code> 放在 <code>/opt/gooseforum</code>，使用专用系统账号 <code>gooseforum</code> 运行。先创建账号与目录，将发行包解压到该目录，并让运行账号拥有所需读写权限。不要用 Web 根目录公开配置或数据库。</p><p>从该目录首次运行程序生成配置，停止程序后修改<strong>已有配置段</strong>：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">env = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;production&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 保留原有 secretKey，不要用本片段覆盖整个文件。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://forum.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5234</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trustedProxies = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stdout&quot;</span></span></code></pre></div><p>同一 TOML 段不能重复声明。此片段省略了数据库和其他现有设置，请合并修改。限制 <code>config.toml</code> 权限，例如 <code>chmod 600 config.toml</code>，并确认文件归运行账号所有。</p><div class="warning custom-block"><p class="custom-block-title">后端监听范围</p><p>生产模式的 HTTP 服务监听所有接口。应通过防火墙或安全组限制 <code>5234</code> 的外部访问，公网流量只经 HTTPS 反代进入；<code>server.url</code> 不会改变监听地址。</p></div><h2 id="配置-systemd" tabindex="-1">配置 systemd <a class="header-anchor" href="#配置-systemd" aria-label="Permalink to &quot;配置 systemd&quot;">​</a></h2><p>将以下示例保存为 <code>/etc/systemd/system/gooseforum.service</code>：</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Unit]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=GooseForum</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">After</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network-online.target</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Wants</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=network-online.target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Service]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=simple</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">User</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=gooseforum</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Group</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=gooseforum</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WorkingDirectory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/opt/gooseforum</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ExecStart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=/opt/gooseforum/GooseForum serve</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Restart</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=on-failure</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RestartSec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=5</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UMask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=0077</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">[Install]</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WantedBy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=multi-user.target</span></span></code></pre></div><p><code>WorkingDirectory</code> 决定配置与相对数据路径。服务用户必须能访问数据库、日志和备份目录。安装服务后：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre></div><h2 id="配置-https-反代" tabindex="-1">配置 HTTPS 反代 <a class="header-anchor" href="#配置-https-反代" aria-label="Permalink to &quot;配置 HTTPS 反代&quot;">​</a></h2><p>把下面的站点块加入 Caddyfile，替换为实际域名：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forum.example.com {</span></span>
<span class="line"><span>    reverse_proxy 127.0.0.1:5234</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>确保域名解析到服务器，并允许证书签发和访问所需的 80 / 443 端口。使用 <a href="https://caddyserver.com/docs/command-line#caddy-validate" target="_blank" rel="noreferrer">Caddy 配置校验命令</a> 检查后再重载；反代配置参考 <a href="https://caddyserver.com/docs/quick-starts/reverse-proxy" target="_blank" rel="noreferrer">Caddy 官方指南</a>。若代理位于容器或另一台机器，后端地址和 <code>trustedProxies</code> 都需要随拓扑调整。</p><h2 id="验证部署" tabindex="-1">验证部署 <a class="header-anchor" href="#验证部署" aria-label="Permalink to &quot;验证部署&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:5234/api/forum/status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://forum.example.com/api/forum/status</span></span></code></pre></div><p>状态接口用于确认 HTTP 与版本检测路径可达，不代表数据库、邮件和对象存储全部健康。还需用真实域名验证注册、登录、发帖、图片、邮件链接和第三方回调。</p><p>上传大文件失败时，同时检查应用上传限制、HTTP 读写超时与反代限制。使用 S3 直传时还要验证桶 CORS，见 <a href="./../configuration/">配置</a>。</p><h2 id="运行维护" tabindex="-1">运行维护 <a class="header-anchor" href="#运行维护" aria-label="Permalink to &quot;运行维护&quot;">​</a></h2><p>保持一个服务实例，按 <a href="./../maintenance/">备份与升级</a> 建立恢复流程。修改监听端口、数据库、日志、缓存后重启；不要因为文件支持热重载就认为所有运行状态都会重新初始化。</p><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/app/console/serve.go" target="_blank" rel="noreferrer">HTTP 监听实现</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/configuration_ZH.md" target="_blank" rel="noreferrer">配置参考</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/site-status.md" target="_blank" rel="noreferrer">状态接口</a>。</p>`,25)])])}const g=a(t,[["render",l]]);export{c as __pageData,g as default};
